201	static bool nvenc_device_available(void)
202	{
203		os_dir_t *dir;
204		struct os_dirent *dirent;
205		bool available = false;
206	
207		if ((dir = os_opendir("/sys/bus/pci/devices")) == NULL) {
208			return true;
209		}
210	
211		while ((dirent = os_readdir(dir)) != NULL) {
212			int id;
213	
214			if (get_id_from_sys(dirent->d_name, "class") != 0x030000 &&
215			    get_id_from_sys(dirent->d_name, "class") != 0x030200) { // 0x030000 = VGA compatible controller
216										    // 0x030200 = 3D controller
217				continue;
218			}
219	
220			if (get_id_from_sys(dirent->d_name, "vendor") != 0x10de) { // 0x10de = NVIDIA Corporation
221				continue;
222			}
223	
224			if ((id = get_id_from_sys(dirent->d_name, "device")) > 0 && !is_blacklisted(id)) {
225				available = true;
226				break;
227			}
228		}
229	
230		os_closedir(dir);
231		return available;
232	}
